// `<data>/claude-plugins/`: Claude Code plugins generated by the app and loaded into every Claude
// tab it starts with `claude --plugin-dir <dir>` (plan: Claude-operable foundation, Task 2).
// `--plugin-dir` loads a plugin for that one session only, so nothing is written to `~/.claude`
// and a Claude started outside the app never sees these skills (Oleg's decision, 2026-10-31).
//
// Layout (one child per source):
//   core/.claude-plugin/plugin.json         {"name":"cc-cockpit","version":<app version>}
//   core/skills/cc-cockpit/SKILL.md         core-skill.md: points the session at `ccc guide`
//   <pluginId>/.claude-plugin/plugin.json   {"name":"ccc-<id, dots as dashes>","version":<plugin's>}
//   <pluginId>/skills/<skillId>/…           the plugin's `contributes.skills` folders (Task 3)
//
// Rebuilt from scratch at every start, like hooks.json: the app version (and the skill text that
// ships with it) changes with an update, and a crashed earlier build may have left debris. Also
// rebuilt whenever the plugin set changes (install, link, update, uninstall, dev reload): a
// plugin's child is copied again from its folder each time, and a plugin that is gone (or no
// longer valid) loses its child in the stale sweep.
//
// Pure Node, no `electron` import: unit tests load it. index.ts passes the version in.
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readdirSync, realpathSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { errorText } from '../../shared/error-text'
import type { SkillContribution } from '../../shared/manifest'
import { readSkillFiles } from '../plugins/skill-files'
import coreSkill from './core-skill.md?raw'
import { warnLog } from '../warn-log'

/** The Claude plugin name of `core/`; its skill is listed to Claude as `cc-cockpit:cc-cockpit`. */
export const CORE_PLUGIN_NAME = 'cc-cockpit'
/** The skill id inside `core/`, equal to the `name:` in core-skill.md's front matter. */
export const CORE_SKILL_ID = 'cc-cockpit'
/** The child folder of the core plugin. Not a valid cockpit plugin id (no dot), so the
 * `<pluginId>/` children can never collide with it. */
export const CORE_DIR = 'core'

/** The text of the core skill's SKILL.md, as written. Exported for tests. */
export const CORE_SKILL_TEXT: string = coreSkill

export interface ClaudePluginsOptions {
  /** `<data>/claude-plugins` (DataPaths.claudePluginsDir). */
  dir: string
  /** The app version, written into core's plugin.json. */
  version: string
  /**
   * The installed plugins that declare skills and validated (state ok), read at each build and
   * again at each spawn (pluginDirsFor). The folder is the installer's, never a plugin's say.
   */
  skillPlugins?: () => readonly SkillSource[]
  /** The plugin ids a project has enabled (its record in main), read at each spawn. */
  enabledPlugins?: (projectId: string) => readonly string[]
  log?: (message: string) => void
  /**
   * Writes one file of a child into its temp folder (default: writeFileSync, mode 0600 or 0700, created
   * exclusively: see writeChild). Tests replace it to fail a build: chmod does not stop root, so a
   * read-only folder would not.
   */
  writeFile?: (path: string, data: string | Buffer) => void
  /** Renames a folder in the publish step of writeChild (default: renameSync). Tests fail it. */
  rename?: (from: string, to: string) => void
}

/** One skill-bearing cockpit plugin, as the installer knows it. */
export interface SkillSource {
  id: string
  version: string
  /** The folder the plugin runs from (install dir or linked folder). */
  dir: string
  /** The cloned commit of a git install; a linked or bundled plugin has none. */
  commit?: string
  skills: readonly SkillContribution[]
}

/** Which source a child was copied from: pluginDirsFor hands it out only while that is still the installed one. */
const sourceIdentity = (p: SkillSource): string => JSON.stringify([p.version, p.commit ?? null])

/**
 * A file of a generated child: a path relative to the child folder, its content, and whether it is
 * written owner-executable (0700, a skill's helper script whose source had the owner's exec bit;
 * otherwise 0600). Without it `./scripts/run.sh` in a skill failed with EACCES (review finding).
 */
interface ChildFile {
  path: string
  text: string | Buffer
  executable?: boolean
}

export class ClaudePlugins {
  private readonly options: ClaudePluginsOptions
  private readonly log: (message: string) => void
  /**
   * Children that exist complete on disk after the last build, with the source each was copied from
   * (sourceIdentity; empty for core). Only these go to `--plugin-dir`.
   */
  private built = new Map<string, string>()
  private resolveReady!: () => void
  /**
   * Resolves once the first build has run (succeeded or not). Restore waits for it before it
   * spawns Claude tabs: TabManager.start is synchronous and reads pluginDirsFor at spawn time, so
   * a tab restored at launch before the tree exists would start without its skills for the whole
   * session (Claude loads plugins only at launch). Never rejects.
   */
  readonly ready: Promise<void>

  constructor(options: ClaudePluginsOptions) {
    this.options = options
    this.log = options.log ?? warnLog
    this.ready = new Promise<void>((resolve) => {
      this.resolveReady = resolve
    })
  }

  /**
   * (Re)write the whole tree. Never throws: a failure (read-only data dir) is logged and the
   * affected child is left out of pluginDirsFor, so a tab starts without that skill rather than
   * with a `--plugin-dir` naming a folder that is missing or half written.
   */
  build(): void {
    try {
      mkdirSync(this.options.dir, { recursive: true, mode: 0o700 })
      const wanted = new Map<string, ChildFile[] | null>([[CORE_DIR, this.coreFiles()]])
      const identities = new Map<string, string>()
      for (const [id, child] of this.pluginChildren()) {
        wanted.set(id, child?.files ?? null)
        if (child) identities.set(id, child.identity)
      }
      const built = new Map<string, string>()
      for (const [name, files] of wanted) {
        // A plugin whose skills could not be read: no child (the sweep below removes an old one,
        // which would be a copy of files that no longer pass).
        if (files === null) continue
        try {
          this.writeChild(name, files)
          built.set(name, identities.get(name) ?? '')
        } catch (err) {
          if (err instanceof DestinationCollision) {
            // Treated as skills that fail the checks: no child, and the sweep removes the old one.
            this.log(`claude-plugins: skills of ${name} skipped: ${err.message}`)
            wanted.set(name, null)
          } else {
            this.log(`claude-plugins: cannot write ${name}: ${errorText(err)}`)
          }
        }
      }
      this.built = built
      // Anything else is stale: a source that went away (an uninstalled or now invalid plugin), or the
      // temp/old folders of a build that crashed between its renames. This assumes one app process
      // per data dir (requestSingleInstanceLock in main/index.ts, keyed on the same dir): another
      // process's in-flight `.core.<pid>.tmp` would be swept here too.
      for (const entry of readdirSync(this.options.dir)) {
        // A child that failed to write keeps its previous complete copy (it is not passed to any
        // tab, see writeChild); one whose skills failed the checks goes.
        if (wanted.get(entry) != null) continue
        // The moved-aside copy of a child whose publish failed and whose rollback failed too
        // (writeChild): it may be the only copy of a tree running sessions read. Put it back when
        // the child is wanted and has no folder; never delete it then.
        const backupOf = /^\.(.+)\.\d+\.old$/.exec(entry)?.[1]
        if (backupOf !== undefined && wanted.get(backupOf) != null) {
          const target = join(this.options.dir, backupOf)
          if (!existsSync(target)) {
            try {
              renameSync(join(this.options.dir, entry), target)
              continue
            } catch (err) {
              this.log(`claude-plugins: cannot restore ${backupOf}: ${errorText(err)}`)
              continue
            }
          }
        }
        try {
          rmSync(join(this.options.dir, entry), { recursive: true, force: true })
        } catch (err) {
          this.log(`claude-plugins: cannot remove stale ${entry}: ${errorText(err)}`)
        }
      }
    } catch (err) {
      this.built = new Map()
      this.log(`claude-plugins: cannot build ${this.options.dir}: ${errorText(err)}`)
    } finally {
      this.resolveReady()
    }
  }

  /**
   * The `--plugin-dir` folders for a Claude tab of `projectId`, read synchronously at each spawn:
   * core first, then each skill-bearing plugin the project enables, by id (a stable order however
   * the plugins were enabled). A plugin enabled in another project only is not passed: its skill
   * would tell Claude about commands this project's host does not run.
   *
   * `built` says what the last build wrote, not what may still be handed out: a plugin revoked
   * since then keeps its child until the queued applyRevocations reaches it, and a pending clone
   * can hold that queue for minutes (review finding: fresh tabs kept loading known-revoked
   * instructions and helpers meanwhile). So each child must also be in the current listing, which
   * reads the installer's view and sees a revocation as soon as the lookup does. A session gets
   * its plugins only at launch, so this is the last look there is.
   *
   * The id alone is not enough: an update moves the record to v2 before the tree is rebuilt (hosts
   * reload in between), and with v1 revoked the id was listed and safe while its child was still
   * v1's instructions and helpers (review finding). So the child must come from the source installed
   * now. A tab started in that window goes without this plugin's skills for its session.
   */
  pluginDirsFor(projectId: string): string[] {
    const dirs = this.built.has(CORE_DIR) ? [join(this.options.dir, CORE_DIR)] : []
    const enabled = [...new Set(this.options.enabledPlugins?.(projectId) ?? [])].sort()
    const current = this.currentSkillPlugins()
    for (const id of enabled) {
      // Only names that are children this build wrote: an id from the project record is never
      // joined into a path unless it is one of them.
      const source = current.get(id)
      if (id !== CORE_DIR && source !== undefined && this.built.get(id) === source) dirs.push(join(this.options.dir, id))
    }
    return dirs
  }

  /**
   * The skill plugins valid right now, with the source of each. A listing that throws counts as none: this runs
   * inside a tab spawn, which must not fail, and a plugin that cannot be checked must not load.
   * Core is not from this listing, so the tab keeps it.
   */
  private currentSkillPlugins(): ReadonlyMap<string, string> {
    try {
      return new Map((this.options.skillPlugins?.() ?? []).map((p) => [p.id, sourceIdentity(p)]))
    } catch (err) {
      this.log(`claude-plugins: cannot list plugin skills: ${errorText(err)}`)
      return new Map()
    }
  }

  /**
   * The child of each skill-bearing plugin, by plugin id: its plugin.json and every skill file, or
   * null when the skills fail the checks now (logged). The files are read again here rather than
   * trusted from the install-time validation: a linked folder (or an installed one, by anyone who
   * can write to it) may have changed since, so the same limits and front-matter rules apply.
   */
  private pluginChildren(): Map<string, { identity: string; files: ChildFile[] } | null> {
    let listed: readonly SkillSource[]
    try {
      listed = this.options.skillPlugins?.() ?? []
    } catch (err) {
      // Core must still be written: a broken plugin listing costs the plugin skills only.
      this.log(`claude-plugins: cannot list plugin skills: ${errorText(err)}`)
      listed = []
    }
    const sources = [...listed].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
    const names = claudePluginNames(sources.map((p) => p.id))
    const out = new Map<string, { identity: string; files: ChildFile[] } | null>()
    for (const p of sources) {
      // Never a path this tree owns: core, or a dot entry the sweep and the temp folders use.
      if (p.id === CORE_DIR || p.id.startsWith('.') || out.has(p.id)) continue
      let realRoot: string
      try {
        realRoot = realpathSync(p.dir)
      } catch (err) {
        this.log(`claude-plugins: skills of ${p.id} skipped: ${errorText(err)}`)
        out.set(p.id, null)
        continue
      }
      const read = readSkillFiles(realRoot, p.skills)
      if (!read.ok) {
        this.log(`claude-plugins: skills of ${p.id} skipped: ${read.error}`)
        out.set(p.id, null)
        continue
      }
      const files: ChildFile[] = [
        { path: join('.claude-plugin', 'plugin.json'), text: pluginJson(names.get(p.id) as string, p.version) }
      ]
      for (const skill of read.skills) {
        for (const f of skill.files) {
          files.push({ path: join('skills', skill.id, ...f.path.split('/')), text: f.data, executable: f.executable })
        }
      }
      out.set(p.id, { identity: sourceIdentity(p), files })
    }
    return out
  }

  private coreFiles(): ChildFile[] {
    return [
      { path: join('.claude-plugin', 'plugin.json'), text: pluginJson(CORE_PLUGIN_NAME, this.options.version) },
      { path: join('skills', CORE_SKILL_ID, 'SKILL.md'), text: CORE_SKILL_TEXT }
    ]
  }

  /**
   * Write one child "atomically": into a sibling temp folder, then swapped in with two renames.
   * A rename onto a non-empty folder fails (ENOTEMPTY), so the old folder is first moved aside.
   * Both renames are synchronous, so no tab spawn in main falls between them; a `claude` already
   * starting in another process could, for that instant, find the folder missing (it then starts
   * without the skill), never half a folder with a plugin.json and no SKILL.md. Same filesystem,
   * so each rename is atomic.
   *
   * Every file is created exclusively (`wx`: O_CREAT|O_EXCL) in a temp folder made empty for this
   * write (removed, then created non-recursively, so a folder that reappeared fails the mkdir).
   * That is the guarantee against two source names that are one name on the app's disk (review
   * finding, rounds 5 and 6): a case-sensitive linked folder can hold the checked `SKILL.md` and a
   * `skill.md`, or `ſkill.md` (U+017F, which APFS folds to `s`), whose front matter was never
   * checked; a plain write would let the second replace the first. Only the destination
   * filesystem knows which names it treats as one, so it is asked: the second create fails with
   * EEXIST (or ENOTDIR/EISDIR when a file and a folder meet) and the plugin's skills are refused.
   * pathCollision in skill-files.ts refuses the common cases earlier, at validation; it is not
   * complete and this does not depend on it. Folders may merge (`Docs/` and `docs/`), which
   * overwrites nothing.
   */
  private writeChild(name: string, files: ChildFile[]): void {
    const dir = this.options.dir
    const tmp = join(dir, `.${name}.${process.pid}.tmp`)
    const old = join(dir, `.${name}.${process.pid}.old`)
    rmSync(tmp, { recursive: true, force: true })
    // A backup left by an earlier failed publish whose rollback failed: if the tree is missing it
    // is the only copy, so it goes back before anything is cleared.
    if (!existsSync(join(dir, name)) && existsSync(old)) {
      renameSync(old, join(dir, name))
    }
    rmSync(old, { recursive: true, force: true })
    mkdirSync(tmp, { mode: 0o700 })
    try {
      for (const file of files) {
        const path = join(tmp, file.path)
        try {
          mkdirSync(join(path, '..'), { recursive: true, mode: 0o700 })
          if (this.options.writeFile) this.options.writeFile(path, file.text)
          else writeFileSync(path, file.text, { mode: file.executable === true ? 0o700 : 0o600, flag: 'wx' })
        } catch (err) {
          const code = (err as NodeJS.ErrnoException).code
          if (code === 'EEXIST' || code === 'ENOTDIR' || code === 'EISDIR') {
            throw new DestinationCollision(
              `${file.path} is the same name as another of its files on this disk (letter case or Unicode form); nothing was published`
            )
          }
          throw err
        }
      }
      const target = join(dir, name)
      const rename = this.options.rename ?? renameSync
      let movedAside = false
      try {
        rename(target, old)
        movedAside = true
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err
      }
      try {
        rename(tmp, target)
      } catch (err) {
        // Publish failed with the old tree moved aside: put it back, so sessions that read its
        // skill files keep them (review finding, round 7). If even that fails the backup stays
        // on disk and the stale sweep in build() restores it rather than deleting it.
        if (movedAside) {
          try {
            rename(old, target)
          } catch (restoreErr) {
            this.log(`claude-plugins: cannot restore ${name}, kept at ${old}: ${errorText(restoreErr)}`)
          }
        }
        throw err
      }
      if (movedAside) rmSync(old, { recursive: true, force: true })
    } catch (err) {
      rmSync(tmp, { recursive: true, force: true })
      throw err
    }
  }
}

/** Two files of a child land on one name in the destination folder (see writeChild). */
class DestinationCollision extends Error {}

/**
 * The Claude plugin name of each cockpit plugin id, `ccc-<id with dots as dashes>`: Claude lists a
 * skill as `<plugin name>:<skill id>`, and plugin names must be unique. Two ids can map to the same
 * name (`a.b-c` and `a-b.c` both give `ccc-a-b-c`), so every one of them gets a short hash
 * of its id appended (the caller sorts `ids`, keeping the result stable across builds): neither
 * name depends on which of them sorts first. Exported for the tests.
 */
export function claudePluginNames(ids: readonly string[]): Map<string, string> {
  const taken = new Set<string>([CORE_PLUGIN_NAME])
  const out = new Map<string, string>()
  const baseOf = (id: string): string => `ccc-${id.replaceAll('.', '-')}`
  const uses = new Map<string, number>()
  for (const id of ids) uses.set(baseOf(id), (uses.get(baseOf(id)) ?? 0) + 1)
  for (const id of ids) {
    const base = baseOf(id)
    const hash = createHash('sha256').update(id).digest('hex')
    // A hashed name can itself be some other id's plain name (`a.b-c-<8 hex>`): a longer hash then.
    let name = uses.get(base)! > 1 ? `${base}-${hash.slice(0, 8)}` : base
    for (const len of [8, 16, 64]) {
      if (!taken.has(name)) break
      name = `${base}-${hash.slice(0, len)}`
    }
    // Every hash length can be some other id's plain name too: count up until unused. Deterministic
    // for a given sorted id set, so restored tabs keep their skill names across rebuilds.
    for (let n = 2; taken.has(name); n++) name = `${base}-${hash}-${n}`
    taken.add(name)
    out.set(id, name)
  }
  return out
}

/** A Claude Code plugin manifest. Claude requires `name`; `version` shows which app wrote it. */
export function pluginJson(name: string, version: string): string {
  return JSON.stringify({ name, version }, null, 2) + '\n'
}

/**
 * When main rebuilds the tree (index.ts wires each event to one method):
 * - `start`: the installed plugins have loaded; the first build, which resolves `ready` (tabs
 *   restored at launch wait for it), so it already holds their skills;
 * - `changed`: the installer's plugin set changed (install, update, uninstall, enable); nothing
 *   before `start`, since load() reports changes and the build after it would rewrite at once;
 * - `revalidated`: a linked plugin's folder changed (dev watch); only when skills are involved:
 *   that plugin is in the tree or has skills now, or the set of valid plugins with skills is not
 *   the one the tree was last built from (the edit took a `ccc` command name from another plugin
 *   or gave one back, and the CLI-name reconciliation demoted or recovered that one: review
 *   finding, its skills stayed in, or stayed out of, new tabs). A rebuild reads every skill
 *   plugin's files on main and swaps the children under live sessions, so a save that changes
 *   none of that must not cost one.
 *
 * The comparison is with the set recorded at the last build, never with a snapshot taken when
 * the reload was asked for (review finding, round 2): two reloads queue in the installer, and
 * both snapshots were taken before either ran. The first demoted a skill plugin and rebuilt
 * without it; the second recovered it, saw it in its own "before" and "after", and skipped the
 * rebuild. Reading the set and building happen in one synchronous step, so whatever the
 * interleaving, a skip means the tree already holds exactly the current set.
 */
export class ClaudePluginsBuilds {
  private started = false
  /** The skill plugin ids the tree was last built from; null before the first build or when unknown. */
  private lastBuilt: ReadonlySet<string> | null = null

  /**
   * `skillPlugins`: the ids of the valid plugins with skills now, the same set `build` writes
   * children for (read synchronously right before each build).
   */
  constructor(
    private readonly build: () => void,
    private readonly skillPlugins: () => readonly string[]
  ) {}

  start(): void {
    this.started = true
    this.rebuild()
  }

  changed(): void {
    if (this.started) this.rebuild()
  }

  /**
   * Runs `revalidate` of plugin `id` (its error propagates, with no build) and rebuilds when skills
   * are involved (see above).
   */
  async revalidated<T>(id: string, revalidate: () => Promise<T>): Promise<T> {
    const result = await revalidate()
    if (!this.started) return result
    const now = this.currentSet()
    const built = this.lastBuilt
    // Not known (the listing threw, now or at the last build): rebuild, build() logs what it can.
    const unknown = now === null || built === null
    if (unknown || built.has(id) || now.has(id) || now.size !== built.size || [...now].some((p) => !built.has(p))) {
      this.rebuild(now)
    }
    return result
  }

  private currentSet(): ReadonlySet<string> | null {
    try {
      return new Set(this.skillPlugins())
    } catch {
      return null
    }
  }

  private rebuild(now: ReadonlySet<string> | null = this.currentSet()): void {
    this.lastBuilt = now
    this.build()
  }
}
